module sv_i_fix_dma_desc_ring(
    input  logic       clk,
    input  logic       rst_n,
    input  logic       fetch_val,
    input  logic       eol,
    input  logic [7:0] next_ptr_in,
    output logic [7:0] cur_desc_addr,
    output logic       ring_complete
);
    // BUG: unconditionally overwrites cur_desc_addr when eol is high
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cur_desc_addr <= 8'd0;
            ring_complete <= 1'b0;
        end else if (fetch_val) begin
            cur_desc_addr <= next_ptr_in;
            ring_complete <= eol;
        end
    end

endmodule

module sv_i_fix_credit_leak(
    input  logic       clk,
    input  logic       rst_n,
    input  logic       push_item,
    input  logic       pop_item,
    output logic [3:0] credit_bank,
    output logic       ret_credit
);
    // BUG: underflow wrap and incorrect reset initialization
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            credit_bank <= 4'd0;
            ret_credit  <= 1'b0;
        end else begin
            ret_credit  <= pop_item;
            credit_bank <= credit_bank + pop_item - push_item;
        end
    end

endmodule

