module sv_i_fix_sram_bank_arb(
    input  logic req0,
    input  logic dest0,
    input  logic req1,
    input  logic dest1,
    output logic grant0,
    output logic grant1,
    output logic conflict
);
    assign grant0   = req0;
    assign conflict = req0 && req1 && (dest0 == dest1);
    // BUG: inverted conflict condition on grant1
    assign grant1   = req1 && (dest0 == dest1);

endmodule

module sv_i_fix_skid_flag_glitch(
    input  logic clk,
    input  logic rst_n,
    input  logic s_valid,
    output logic s_ready,
    output logic m_valid,
    input  logic m_ready
);
    logic [1:0] state;

    // BUG: incorrect state transition from SKID to BUSY
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 2'd0;
        end else begin
            case (state)
                2'd0: if (s_valid) state <= 2'd1;
                2'd1: if (s_valid && !m_ready) state <= 2'd2;
                      else if (!s_valid && m_ready) state <= 2'd0;
                2'd2: if (m_ready) state <= 2'd0; // BUG: drops directly to 0
            endcase
        end
    end

    assign s_ready = (state != 2'd2);
    assign m_valid = (state != 2'd0);

endmodule

