module sv_i_fix_fifo_gray_bin(
    input  logic [3:0] gray_in,
    output logic [3:0] bin_out
);
    assign bin_out[3] = gray_in[3];
    assign bin_out[2] = bin_out[3] ^ gray_in[2];
    assign bin_out[1] = bin_out[2] ^ gray_in[1];
    // BUG: does not cascade from bin_out[1]
    assign bin_out[0] = gray_in[1] ^ gray_in[0];

endmodule

