module sv_i_fix_sram_read_priority(
    input  logic clk,
    input  logic rst_n,
    input  logic req_cpu,
    input  logic req_dma,
    output logic grant_cpu,
    output logic grant_dma,
    output logic [1:0] cpu_burst_cnt
);
    logic [1:0] cnt;

    // BUG: fails to reset cnt on DMA grant
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 2'd0;
        end else if (req_cpu && req_dma && (cnt == 2'd3)) begin
            // BUG: forgot cnt <= 0
        end else if (req_cpu) begin
            cnt <= cnt + 1'b1;
        end else begin
            cnt <= 2'd0;
        end
    end

    assign grant_dma     = req_dma && (!req_cpu || (cnt == 2'd3));
    assign grant_cpu     = req_cpu && !grant_dma;
    assign cpu_burst_cnt = cnt;

endmodule

module sv_i_fix_csa_sign_ext(
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [7:0] c,
    output logic [7:0] sum_out,
    output logic [7:0] carry_out
);
    logic [7:0] c_gen;
    assign sum_out = a ^ b ^ c;
    assign c_gen   = (a & b) | (b & c) | (a & c);
    // BUG: shifted right instead of left
    assign carry_out = {1'b0, c_gen[7:1]};

endmodule
